document.addEventListener("DOMContentLoaded",init);const STORE_PAGE_SIZE=20;let storesLoadedLimit=STORE_PAGE_SIZE;let storesHasMore=false;let storesQuery="";async function init(){document.getElementById("stores-load-more").addEventListener("click",onLoadMore);wireStoresSearch();whenIdle(loadCartStores);await loadStores()}function wireStoresSearch(){const form=document.getElementById("stores-search-form");const input=document.getElementById("stores-search-input");let debounceTimer=null;function runSearch(){storesQuery=input.value.trim();storesLoadedLimit=STORE_PAGE_SIZE;loadStores()}form.addEventListener("submit",e=>{e.preventDefault();clearTimeout(debounceTimer);runSearch()});input.addEventListener("input",()=>{clearTimeout(debounceTimer);debounceTimer=setTimeout(runSearch,300)})}async function loadStores(){const statusEl=document.getElementById("stores-status");const stopLoading=startLoadingMessage(statusEl);const request=Api.get("listStores",{limit:storesLoadedLimit,q:storesQuery});window.__criticalReady=request;const res=await request;stopLoading();if(!res.ok){showLoadFailedMessage(statusEl);return}if(res.stores.length===0){statusEl.textContent=storesQuery?`No stores match "${storesQuery}" — try a different island or village.`:"No stores are open yet — check back soon.";document.getElementById("store-list").innerHTML="";document.getElementById("stores-load-more").classList.add("hidden");return}storesHasMore=!!res.hasMore;statusEl.textContent=`${res.stores.length} of ${res.total} store${res.total===1?"":"s"} shown.`;document.getElementById("store-list").innerHTML=res.stores.map(store=>renderStoreCard(store)).join("");document.getElementById("stores-load-more").classList.toggle("hidden",!storesHasMore);markCartStoresInList()}async function onLoadMore(){storesLoadedLimit+=STORE_PAGE_SIZE;await loadStores()}function hideCartStores(){const section=document.getElementById("cart-stores");document.getElementById("cart-store-list").innerHTML="";section.classList.add("is-loaded");section.classList.add("hidden")}async function loadCartStores(){const slugs=cartStoreSlugs();if(slugs.length===0)return;const results=await Promise.all(slugs.map(slug=>Api.get("getStorePublicInfo",{storeSlug:slug}).catch(()=>null)));const stores=results.map((res,i)=>res&&res.ok&&res.store?Object.assign({storeSlug:slugs[i]},res.store):null).filter(Boolean);if(stores.length===0){hideCartStores();return}document.getElementById("cart-store-list").innerHTML=stores.map(store=>renderStoreCard(store,{resume:true})).join("");document.getElementById("cart-stores").classList.add("is-loaded");markCartStoresInList()}function markCartStoresInList(){const slugs=cartStoreSlugs();if(slugs.length===0)return;document.querySelectorAll("#store-list .store-card").forEach(card=>{const slug=card.dataset.storeSlug;if(!slug||slugs.indexOf(slug)===-1)return;card.classList.add("is-in-cart");if(card.querySelector(".store-card-cart-flag"))return;const flag=document.createElement("span");flag.className="store-card-cart-flag";flag.textContent="In your cart";(card.querySelector(".store-card-info")||card).prepend(flag)})}function renderStoreCard(store,opts){const resume=!!(opts&&opts.resume);const logo=store.logoUrl?`<img class="store-card-logo" src="${escapeHtml(optimizedImageUrl(store.logoUrl,IMG_W.logo))}" alt="" loading="lazy" decoding="async">`:`<div class="store-card-logo-placeholder" aria-hidden="true">${escapeHtml(initials(store.storeName))}</div>`;const location=storeLocationLabel(store.island,store.village);const displayName=location?`${store.storeName} | ${location}`:store.storeName;return`\n    <a class="store-card${resume?" store-card--resume":""}" data-store-slug="${escapeHtml(store.storeSlug)}" href="store.html?store=${encodeURIComponent(store.storeSlug)}">\n      ${logo}\n      <div class="store-card-info">\n        <h3>${escapeHtml(displayName)}</h3>\n        <div class="store-card-meta">\n          ${store.phone?`<span class="store-phone">${escapeHtml(store.phone)}</span>`:""}\n          ${renderDeliveryIcons({truck:store.deliveryTruck,ship:store.deliveryShip,airCargo:store.deliveryAirCargo,pickPay:store.deliveryPickPay,truckCost:store.deliveryTruckCost,shipCost:store.deliveryShipCost,airCargoCost:store.deliveryAirCargoCost})}\n        </div>\n        <p class="helper-text">${resume?'<span class="store-card-resume">Continue shopping →</span>':"Visit store →"}</p>\n      </div>\n    </a>\n  `}